package android.content;import java.util.*;public class SharedPreferences{final Map<String,Object> m=new HashMap<>();public Map<String,?> getAll(){return new HashMap<>(m);}public boolean contains(String k){return m.containsKey(k);}public String getString(String k,String d){return (String)m.getOrDefault(k,d);}public long getLong(String k,long d){return ((Number)m.getOrDefault(k,d)).longValue();}public boolean getBoolean(String k,boolean d){return (Boolean)m.getOrDefault(k,d);}public Editor edit(){return new Editor();}public class Editor{public Editor putString(String k,String v){m.put(k,v);return this;}public Editor putLong(String k,long v){m.put(k,v);return this;}public Editor putBoolean(String k,boolean v){m.put(k,v);return this;}public Editor remove(String k){m.remove(k);return this;}public void apply(){}public boolean commit(){return true;}}}